"""Bounded C89 source behavior; native pointer layout is proved by IDO replay."""
import os
from pathlib import Path
import subprocess
import tempfile
import unittest
ROOT = Path(__file__).resolve().parents[4]
WORK = Path(__file__).resolve().parent
class Semantics(unittest.TestCase):
    def run_c(self, address, body, match=True):
        source = ROOT/'cloud/matches/boot_tail'/('func_'+address+'.c') if match else WORK/'nonmatch'/('func_'+address+'.c')
        with tempfile.TemporaryDirectory() as t:
            p = Path(t)
            (p/'test.c').write_text('#include <assert.h>\n#include <stddef.h>\n#include <string.h>\n#include "'+str(source)+'"\n'+body)
            subprocess.run(['cc','-std=c89','-pedantic-errors','-Wall','-Wextra','-Werror','-fsanitize=address,undefined','-no-pie',str(p/'test.c'),'-o',str(p/'test')],check=True,capture_output=True)
            subprocess.run([str(p/'test')],check=True,capture_output=True,env=dict(os.environ,ASAN_OPTIONS='detect_leaks=0:halt_on_error=1',UBSAN_OPTIONS='halt_on_error=1'))
    def test_translated_record_80018C2C(self):
        self.run_c('80018C2C','\nVoiceRecord D_80043EB8[8];static u32 translated;static int phase,expected_row;\ntypedef char layout[sizeof(VoiceRecord)==4088 && offsetof(VoiceRecord,activeFC0)==4032 && offsetof(VoiceRecord,inactiveFC1)==4033 && offsetof(VoiceRecord,flagsFEE)==4078 && offsetof(VoiceRecord,pendingFF0)==4080?1:-1];\nu32 func_80017644(u32 id){assert(id==0x12345678U);assert(phase++==0);return translated;}\nvoid func_8001734C(VoiceRecord *r){assert(phase++==1&&r==D_80043EB8+expected_row&&r->activeFC0==0);r->identifier=0x76543210U;r->inactiveFC1=7;}\nvoid func_8001729C(VoiceRecord *r){assert(phase++==2&&r==D_80043EB8+expected_row);r->identifier=0x89ABCDEFU;r->inactiveFC1=9;}\nint main(void){int row,tag,active,inactive;VoiceRecord expected[8];u8 b[3]={0,1,255};for(row=0;row<8;row++)for(tag=0;tag<2;tag++)for(active=0;active<3;active++)for(inactive=0;inactive<3;inactive++){memset(D_80043EB8,0xA5,sizeof(D_80043EB8));D_80043EB8[row].activeFC0=b[active];D_80043EB8[row].inactiveFC1=b[inactive];memcpy(expected,D_80043EB8,sizeof(expected));translated=(u32)row|(tag?0x80000000U:0);expected_row=row;phase=0;func_80018C2C(0x12345678U);if(active&&!inactive){if(tag){expected[row].flagsFEE|=8;}else{expected[row].activeFC0=0;expected[row].identifier=0x89ABCDEFU;expected[row].inactiveFC1=9;}}assert(phase==(active&&!inactive&&!tag?3:1));assert(memcmp(expected,D_80043EB8,sizeof(expected))==0);}memcpy(expected,D_80043EB8,sizeof(expected));translated=0xFFFFFFFFU;phase=0;func_80018C2C(0x12345678U);assert(phase==1&&memcmp(expected,D_80043EB8,sizeof(expected))==0);return 0;}\n',True)
    def test_translated_record_80018D40(self):
        self.run_c('80018D40','\nVoiceRecord D_80043EB8[8];static u32 translated;static int phase,expected_row;\ntypedef char layout[sizeof(VoiceRecord)==4088 && offsetof(VoiceRecord,activeFC0)==4032 && offsetof(VoiceRecord,inactiveFC1)==4033 && offsetof(VoiceRecord,flagsFEE)==4078 && offsetof(VoiceRecord,pendingFF0)==4080?1:-1];\nu32 func_80017644(u32 id){assert(id==0x12345678U);assert(phase++==0);return translated;}\nvoid func_8001734C(VoiceRecord *r){assert(phase++==1&&r==D_80043EB8+expected_row&&r->activeFC0==0);r->identifier=0x76543210U;r->inactiveFC1=7;}\nvoid func_8001729C(VoiceRecord *r){assert(phase++==2&&r==D_80043EB8+expected_row);r->identifier=0x89ABCDEFU;r->inactiveFC1=9;}\nint main(void){int row,tag,active,inactive;VoiceRecord expected[8];u8 b[3]={0,1,255};for(row=0;row<8;row++)for(tag=0;tag<2;tag++)for(active=0;active<3;active++)for(inactive=0;inactive<3;inactive++){memset(D_80043EB8,0xA5,sizeof(D_80043EB8));D_80043EB8[row].activeFC0=b[active];D_80043EB8[row].inactiveFC1=b[inactive];memcpy(expected,D_80043EB8,sizeof(expected));translated=(u32)row|(tag?0x80000000U:0);expected_row=row;phase=0;func_80018D40(0x12345678U);if(active&&!inactive){if(tag){expected[row].pendingFF0=0;}else{expected[row].activeFC0=0;expected[row].identifier=0x89ABCDEFU;expected[row].inactiveFC1=9;}}if(!tag)expected[row].inactiveFC1=1;assert(phase==(active&&!inactive&&!tag?3:1));assert(memcmp(expected,D_80043EB8,sizeof(expected))==0);}memcpy(expected,D_80043EB8,sizeof(expected));translated=0xFFFFFFFFU;phase=0;func_80018D40(0x12345678U);assert(phase==1&&memcmp(expected,D_80043EB8,sizeof(expected))==0);return 0;}\n',True)
    def test_ordered_pool_initializer(self):
        self.run_c('8001E9B0','\nu32 D_80050A4C;SequenceNode D_80050A50[32];SequenceNode *D_80050C50,*D_80050C54;\nint main(void){int i,pass;for(i=0;i<32;i++){D_80050A50[i].key=0xDEAD0000U+i;D_80050A50[i].value=0xCAFE0000U+i;D_80050A50[i].next=D_80050A50+31-i;D_80050A50[i].previous=D_80050A50+i;}for(pass=0;pass<2;pass++){D_80050A4C=99;D_80050C50=D_80050A50+8;D_80050C54=0;func_8001E9B0();assert(!D_80050A4C&&!D_80050C50&&D_80050C54==D_80050A50);for(i=0;i<32;i++){assert(D_80050A50[i].next==(i==31?0:D_80050A50+i+1));assert(D_80050A50[i].previous==(i==0?0:D_80050A50+i-1));assert(D_80050A50[i].key==0xDEAD0000U+i&&D_80050A50[i].value==0xCAFE0000U+i);}}return 0;}\n',True)
    def test_channel_and_group_unlink(self):
        self.run_c('8001EE9C','\nChannelLink D_800504C8[32];u8 D_80050548[256];GroupLink D_80050648[256];u16 D_80050A48;\ntypedef char layout[sizeof(ChannelLink)==4&&sizeof(GroupLink)==4&&offsetof(VoicePrefix,identifier60)==96?1:-1];\nint main(void){int a,b,c,d,e;u8 ids[3]={0,7,31},channels[3]={0,127,255};u16 active[3]={0,1,2};ChannelLink links[32];u8 heads[256];GroupLink groups[256];VoicePrefix state;u16 head;u8 id,ch,prev,next;u16 gp,gn;for(a=0;a<3;a++)for(b=0;b<3;b++)for(c=0;c<4;c++)for(d=0;d<4;d++)for(e=0;e<3;e++){id=ids[a];ch=channels[b];prev=c&1?3:255;next=c&2?4:255;gp=d&1?3:65535;gn=d&2?4:65535;memset(D_800504C8,0xA5,sizeof(D_800504C8));memset(D_80050548,0xA5,sizeof(D_80050548));memset(D_80050648,0xA5,sizeof(D_80050648));D_800504C8[id].previous=prev;D_800504C8[id].next=next;D_800504C8[id].active=active[e];D_80050648[ch].previous=gp;D_80050648[ch].next=gn;D_80050A48=ch;memcpy(links,D_800504C8,sizeof(links));memcpy(heads,D_80050548,sizeof(heads));memcpy(groups,D_80050648,sizeof(groups));head=D_80050A48;memset(&state,0,sizeof(state));state.channel2E=ch;state.identifier60=0xABCDEF00U|id;func_8001EE9C(&state);if(active[e]==1){if(prev==255)heads[ch]=next;else links[prev].next=next;if(next!=255)links[next].previous=prev;if(prev==255&&next==255){if(gp==65535)head=gn;else groups[gp].next=gn;if(gn!=65535)groups[gn].previous=gp;}links[id].active=0;}assert(memcmp(links,D_800504C8,sizeof(links))==0&&memcmp(heads,D_80050548,sizeof(heads))==0&&memcmp(groups,D_80050648,sizeof(groups))==0&&head==D_80050A48);}return 0;}\n',True)
    def test_emitter_copy_gain_and_gate(self):
        self.run_c('8001D0F0','\nu8 D_8002C630;static int phase;static Emitter *selected;\nvoid func_80014594(void){assert(phase++==0);selected->unknown24=0x12345678U;}\nvoid func_800145DC(void){assert(phase++==1);selected->unknown24=0xABCDEF01U;}\nint main(void){Emitter s,e;Vector p,v;int level,k,enabled;float current[5]={-1.0f,0.0f,0.3f,1.0f,2.0f};p.x=1.0f;p.y=-2.0f;p.z=3.0f;v.x=-4.0f;v.y=5.0f;v.z=-6.0f;for(enabled=0;enabled<2;enabled++)for(level=0;level<256;level++)for(k=0;k<5;k++){memset(&s,0,sizeof(s));s.current2C=current[k];e=s;selected=&s;phase=0;D_8002C630=enabled;assert(func_8001D0F0(&s,&p,&v,(u8)level)==enabled);if(enabled){e.position=p;e.velocity=v;e.gain28=(float)level/127.0f;if(e.gain28<e.current2C)e.current2C=e.gain28;e.unknown24=0xABCDEF01U;}assert(phase==2*enabled&&memcmp(&s,&e,sizeof(s))==0);}return 0;}\n',False)
    def test_track_fraction_signed_carry_modulo(self):
        self.run_c('800180A0','\nContext *D_8004BE80;\ntypedef char layout[sizeof(Track)==40&&offsetof(Context,tracks)==0x568&&offsetof(Context,whole11C)==0x11C?1:-1];\nstatic long signed_word(unsigned long v){v&=0xFFFFFFFFUL;return v>=0x80000000UL?(long)v-4294967296L:(long)v;}\nint main(void){Context c,e;u32 v[5]={0,1,65535,0xFFFFFFFFU,0x80000000U};int a,b,k,i;unsigned long raw,word;long carry;D_8004BE80=&c;for(a=0;a<5;a++)for(b=0;b<5;b++)for(k=0;k<5;k++){memset(&c,0xA5,sizeof(c));c.fraction118=v[b];c.whole11C=(s32)signed_word(v[k]);for(i=0;i<64;i++){c.tracks[i].fraction=v[a];c.tracks[i].whole=(s32)signed_word(v[(i+k)%5]);c.tracks[i].active0C=i&1;c.tracks[i].active10=i&2;c.tracks[i].active14=i&4;}e=c;for(i=0;i<64;i++)if(i&7){raw=((unsigned long)e.tracks[i].fraction+e.fraction118)&0xFFFFFFFFUL;carry=signed_word(raw);carry=carry<0?-((-carry+65535L)/65536L):carry/65536L;e.tracks[i].fraction=(u32)(raw&65535);word=((unsigned long)(u32)e.tracks[i].whole+(unsigned long)carry+(unsigned long)(u32)e.whole11C)&0xFFFFFFFFUL;e.tracks[i].whole=(s32)signed_word(word);}func_800180A0();assert(memcmp(&c,&e,sizeof(c))==0);}return 0;}\n',False)
if __name__=='__main__':unittest.main()
